import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [h, w] = input[0].split(" ").map(Number);
const grid = input.slice(1, h + 1);

// dist[y * w + x] = スタートからの最短距離（未訪問は -1）
const dist = new Int32Array(h * w).fill(-1);
const queue = new Int32Array(h * w);
let head = 0;
let tail = 0;
dist[0] = 0;
queue[tail++] = 0;

const dy = [-1, 1, 0, 0];
const dx = [0, 0, -1, 1];
while (head < tail) {
  const cur = queue[head++];
  const y = Math.floor(cur / w);
  const x = cur % w;
  for (let d = 0; d < 4; d++) {
    const ny = y + dy[d];
    const nx = x + dx[d];
    if (ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
    if (grid[ny][nx] === "#" || dist[ny * w + nx] !== -1) continue;
    dist[ny * w + nx] = dist[cur] + 1;
    queue[tail++] = ny * w + nx;
  }
}
console.log(dist[h * w - 1]);
